import{_ as t}from"./chunks/gather-evidence.CFBdlZLj.js";import{_ as a,o,c as r,ak as n}from"./chunks/framework.sV-XtlWr.js";const p=JSON.parse('{"title":"Your first failure, explained","description":"","frontmatter":{"title":"Your first failure, explained","lang":"en-US"},"headers":[],"relativePath":"guide/first-failure.md","filePath":"guide/first-failure.md","lastUpdated":1788801735000}'),i={name:"guide/first-failure.md"};function s(l,e,h,u,d,c){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="your-first-failure-explained" tabindex="-1">Your first failure, explained <a class="header-anchor" href="#your-first-failure-explained" aria-label="Permalink to &quot;Your first failure, explained&quot;">​</a></h1><p>You&#39;ve landed your first run (<a href="./getting-started.html">Getting started</a>) and one test is red. This page walks through reading it. Piwi lays a failing execution out <strong>diagnosis-first</strong> — one column, top to bottom: <em>what</em> broke, <em>why</em>, <em>what to do next</em>, then the evidence and more ways to fix — so you&#39;re not scrolling a trace hoping to spot the problem.</p><p>Open the failing test from the run page (click its row) to reach its <strong>execution page</strong>.</p><figure><img src="'+t+'" alt="A failing execution laid out diagnosis-first: one situation block — headline, most likely, situation and next step — and one evidence card with tabs"><figcaption>One failing execution, read top to bottom: the situation block that says what broke, what is most likely and what to do, then the evidence.</figcaption></figure><h2 id="_1-the-headline-—-what-broke" tabindex="-1">1. The headline — what broke <a class="header-anchor" href="#_1-the-headline-—-what-broke" aria-label="Permalink to &quot;1. The headline — what broke&quot;">​</a></h2><p>The top of the page is one <strong>situation block</strong>. Its heading is a plain-English sentence built from the Playwright error, before you read a word of the raw error itself:</p><blockquote><p><code>getByRole(&#39;button&#39;, { name: &#39;Pay&#39; }) never became enabled — click timed out after 30 s</code></p></blockquote><p>The verbatim error is one click away under <strong>Raw error</strong> — Piwi never rewrites it, it only leads with a readable summary. That same headline names the test on the run page, in <a href="/features/notifications.html">alerts</a>, in the <a href="./ci.html#pull-request-feedback">pull-request comment</a>, and in your terminal, so you recognize it everywhere.</p><h2 id="_2-most-likely-—-why" tabindex="-1">2. Most likely — why <a class="header-anchor" href="#_2-most-likely-—-why" aria-label="Permalink to &quot;2. Most likely — why&quot;">​</a></h2><p>Under the headline, the <strong>Most likely</strong> line gives you the one explanation, not a pile of them. When several <strong><a href="/features/evidence.html#clues">clues</a></strong> — deterministic, rule-based findings correlated from the evidence, <em>no model runs</em> — form a known combination, it reads as one sentence:</p><blockquote><p><em>&quot;the Pay button stayed disabled because POST /api/checkout/quote was still in flight (28 s); the console said so 1.5 s before the click gave up&quot;</em></p></blockquote><p>It carries a strength chip and how many clues <strong>agree</strong>; a <strong>more</strong> disclosure lists every clue, each with a <strong>citation</strong> to the evidence it came from — click it and the page jumps to the proof.</p><h2 id="_3-the-situation-—-what-s-going-on" tabindex="-1">3. The situation — what&#39;s going on <a class="header-anchor" href="#_3-the-situation-—-what-s-going-on" aria-label="Permalink to &quot;3. The situation — what&#39;s going on&quot;">​</a></h2><p>Below the explanation, the <strong>situation</strong> sentence puts the failure in context in one line: since when it&#39;s been failing (and on which commit), how many other tests share the same cause and the <a href="/features/failure-clusters.html">cluster</a> they join, whether an earlier fix regressed, and who owns it. An exceptional case — a new regression, a pass on retry, an infrastructure blip — leads the sentence as its one badge.</p><h2 id="_4-next-—-what-to-do" tabindex="-1">4. Next — what to do <a class="header-anchor" href="#_4-next-—-what-to-do" aria-label="Permalink to &quot;4. Next — what to do&quot;">​</a></h2><p>The <strong>Next</strong> line names the one thing to do, chosen for you rather than offered as a menu: apply the diagnosed patch, replace the <a href="/features/locator-healing.html">broken locator</a>, reproduce it locally, re-run in CI, or mark the cluster resolved — with the button to do it, and a word on why it&#39;s the step. Where the work is a code change, the exact command to re-run this test trails it as <strong>Copy retry command</strong>. The full policy is on the <a href="/features/fix-plans.html#the-next-step">fix-plans page</a>.</p><h2 id="_5-the-evidence-—-see-it" tabindex="-1">5. The evidence — see it <a class="header-anchor" href="#_5-the-evidence-—-see-it" aria-label="Permalink to &quot;5. The evidence — see it&quot;">​</a></h2><p>One <strong>evidence card</strong> with tabs — <strong>Timeline, Screen, Source, Network, Console, State, Performance</strong> — opens on the tab the strongest clue points at. The one to know first is <strong>Timeline</strong>: it places the test&#39;s steps, console entries, network requests and backend logs on a single clock and marks the <strong>moment of failure</strong>, so &quot;console (1) / network (3)&quot; becomes <em>what the app was doing when the test gave up</em>. <strong>Screen</strong> holds the failure screenshot, the visual diff against the last green run, and the failure-time page state; <strong>Source</strong> shows the test source as a real call stack, so a failure inside a helper shows the helper.</p><div class="tip custom-block"><p class="custom-block-title">Most of this needs one file</p><p>The error, trace, headline and clustering work with the reporter alone. The console, network, Web Vitals, failure-time snapshot and locator healing come from the <a href="./capture-fixtures.html">capture fixtures</a> — one file in your test setup. If a tab is dimmed, that&#39;s usually why; it opens to say so.</p></div><h2 id="_6-more-ways-to-fix" tabindex="-1">6. More ways to fix <a class="header-anchor" href="#_6-more-ways-to-fix" aria-label="Permalink to &quot;6. More ways to fix&quot;">​</a></h2><p>You&#39;ve already got the one recommended step above. Below the evidence, <strong>More ways to fix</strong> is the folded toolbox holding every <em>other</em> way to fix, verify or reproduce — each a section collapsed to one line, so no wall of code opens by default. The section the <strong>Next</strong> step points at is already open; unfold the rest as you need them:</p><ul><li>a <strong><a href="/features/locator-healing.html">replacement locator</a></strong> when a locator broke, ranked by stability and in your suite&#39;s own style;</li><li>the <strong><a href="/features/ai-diagnosis.html">AI diagnosis</a></strong> and its validated patch, when you&#39;ve configured a model (optional, and grounded in your real diff);</li><li><strong>verify</strong> — re-run in CI or run it locally — <strong>reproduce and bisect</strong>, whether this failure was <strong>fixed before</strong>, the tests it <strong>blocked</strong>, and the <strong><a href="/features/fix-plans.html">fix plan</a></strong> as Markdown.</li></ul><p>The point is to leave with something to do, not just something to read.</p><h2 id="you-re-not-reading-it-alone" tabindex="-1">You&#39;re not reading it alone <a class="header-anchor" href="#you-re-not-reading-it-alone" aria-label="Permalink to &quot;You&#39;re not reading it alone&quot;">​</a></h2><p>This execution is one member of a <strong><a href="/features/failure-clusters.html">failure cluster</a></strong> — Piwi groups every test that failed for the same reason, so forty red tests become three problems you triage once. From the cluster you get the full <a href="/features/ai-diagnosis.html">fix plan</a>, the owner, and — once a later run passes every test it covers — <a href="/features/ai-diagnosis.html#did-the-fix-work">confirmation the fix held</a>.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="/features/evidence.html">Failure evidence</a> — the full reference for everything on this page</li><li><a href="/features/failure-clusters.html">Failure clusters &amp; the inbox</a> — triaging failures as groups</li><li><a href="./capture-fixtures.html">Capture fixtures</a> — the one file that unlocks the richer evidence</li><li><a href="./concepts.html">Core concepts</a> — run, execution, cluster, fingerprint, baseline</li></ul>',27)])])}const m=a(i,[["render",s]]);export{p as __pageData,m as default};
